import { n as TSS_SERVER_FUNCTION } from "./ssr.mjs";
//#region node_modules/.nitro/vite/services/ssr/assets/db-CoBHDOWb.js
var createServerRpc = (serverFnMeta, splitImportFn) => {
	const url = "/_serverFn/" + serverFnMeta.id;
	return Object.assign(splitImportFn, {
		url,
		serverFnMeta,
		[TSS_SERVER_FUNCTION]: true
	});
};
var _0002_archive_default = "create table if not exists about_sections (\n  id serial primary key,\n  slug text not null unique,\n  title text not null,\n  body text not null,\n  sort_order integer not null default 0\n);\n\ncreate table if not exists history_articles (\n  id serial primary key,\n  slug text not null unique,\n  title text not null,\n  excerpt text not null default '',\n  body text not null,\n  period text not null,\n  period_order integer not null default 0,\n  approx_year text not null default '',\n  image text not null default '',\n  sources text not null default '',\n  author text not null default 'Archive editor',\n  published_at date not null default current_date,\n  updated_at date not null default current_date,\n  published boolean not null default true,\n  is_demo boolean not null default false\n);\ncreate index if not exists history_articles_period_idx on history_articles (period_order, published_at);\n\ncreate table if not exists history_images (\n  id serial primary key,\n  article_id integer not null references history_articles(id) on delete cascade,\n  image text not null,\n  caption text not null default '',\n  sort_order integer not null default 0\n);\n\ncreate table if not exists personalities (\n  id serial primary key,\n  slug text not null unique,\n  name text not null,\n  photograph text not null default '',\n  birth_date text not null default '',\n  death_date text not null default '',\n  profession text not null default '',\n  education text not null default '',\n  biography text not null default '',\n  achievements text not null default '',\n  contributions text not null default '',\n  connection text not null default '',\n  sources text not null default '',\n  published boolean not null default true,\n  is_demo boolean not null default false\n);\n\ncreate table if not exists personality_photos (\n  id serial primary key,\n  personality_id integer not null references personalities(id) on delete cascade,\n  image text not null,\n  caption text not null default '',\n  sort_order integer not null default 0\n);\n\ncreate table if not exists archive_items (\n  id serial primary key,\n  item_code text not null unique,\n  title text not null,\n  author text not null default '',\n  year_label text not null default '',\n  period text not null default '',\n  language text not null default '',\n  script text not null default '',\n  material text not null default '',\n  page_count integer not null default 0,\n  category text not null,\n  keywords text not null default '',\n  description text not null default '',\n  significance text not null default '',\n  source_owner text not null default '',\n  cover_image text not null default '',\n  references_text text not null default '',\n  published boolean not null default true,\n  is_demo boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\ncreate index if not exists archive_items_category_idx on archive_items (category);\ncreate index if not exists archive_items_search_idx on archive_items (title, author, year_label);\n\ncreate table if not exists manuscript_pages (\n  id serial primary key,\n  item_id integer not null references archive_items(id) on delete cascade,\n  page_number integer not null,\n  image text not null,\n  caption text not null default '',\n  description text not null default '',\n  unique (item_id, page_number)\n);\n\ncreate table if not exists hukamnamas (\n  id serial primary key,\n  date date not null unique,\n  ang text not null default '',\n  title text not null default 'Hukamnama',\n  image text not null default '',\n  punjabi_text text not null default '',\n  translation text not null default '',\n  source text not null default '',\n  published boolean not null default true,\n  is_demo boolean not null default false,\n  created_at timestamptz not null default now()\n);\ncreate index if not exists hukamnamas_date_idx on hukamnamas (date desc);\n\ncreate table if not exists galleries (\n  id serial primary key,\n  slug text not null unique,\n  title text not null,\n  description text not null default '',\n  category text not null,\n  date_label text not null default '',\n  cover_image text not null default '',\n  published boolean not null default true,\n  is_demo boolean not null default false\n);\n\ncreate table if not exists gallery_images (\n  id serial primary key,\n  gallery_id integer not null references galleries(id) on delete cascade,\n  image text not null,\n  caption text not null default '',\n  date_label text not null default '',\n  sort_order integer not null default 0\n);\n\ncreate table if not exists videos (\n  id serial primary key,\n  title text not null,\n  description text not null default '',\n  youtube_url text not null default '',\n  thumbnail text not null default '',\n  event_date date,\n  category text not null,\n  duration text not null default '',\n  published boolean not null default true,\n  is_demo boolean not null default false\n);\n\ncreate table if not exists live_events (\n  id serial primary key,\n  title text not null,\n  description text not null default '',\n  event_date date,\n  location text not null default '',\n  youtube_url text not null default '',\n  thumbnail text not null default '',\n  is_live boolean not null default false,\n  start_time text not null default '',\n  end_time text not null default '',\n  is_demo boolean not null default false\n);\n\ncreate table if not exists news (\n  id serial primary key,\n  slug text not null unique,\n  title text not null,\n  excerpt text not null default '',\n  body text not null,\n  image text not null default '',\n  author text not null default 'Archive editor',\n  published_at date not null default current_date,\n  category text not null default 'Village',\n  published boolean not null default true,\n  is_demo boolean not null default false\n);\ncreate index if not exists news_published_idx on news (published_at desc);\n\ncreate table if not exists contributions (\n  id serial primary key,\n  category text not null,\n  description text not null,\n  filename text not null default '',\n  consent boolean not null default false,\n  created_at timestamptz not null default now(),\n  reviewed boolean not null default false\n);\n\ncreate table if not exists contact_messages (\n  id serial primary key,\n  subject text not null,\n  message text not null,\n  created_at timestamptz not null default now()\n);\n";
var _0003_seed_default = "insert into about_sections (slug, title, body, sort_order) values\n('introduction', 'Introduction',\n $$Mallu Nangal is a village in Amritsar district, Punjab, India. In official Census of India records the settlement is also spelled Malu Nangal. This website is a public archive for the village’s history, families, religious life, photographs, and documents. Where a fact has not yet been verified by the archive, it is left blank or clearly marked as demo layout content.$$, 1),\n('location', 'Location',\n $$Mallu Nangal lies in Amritsar district in the Majha region of Punjab. Census and village directories place it in Ajnala tehsil / the Harsha Chhina (Harsa Chhina) development block, with some records also naming Lopoke tehsil. The PIN code is 143101. Raja Sansi is recorded as the nearest town, about five kilometres away. Neighbouring villages named in public directories include Adliwala, Loharka Kalan, Ranewali, Jagdev Kalan and Loharka Khurd. Amritsar city is the district headquarters. GeoNames lists the populated place at approximately 31.75° N, 74.85° E, elevation about 230 metres.$$, 2),\n('overview', 'Village overview',\n $$According to the Census of India 2011, Malu Nangal (village code 037396) had a population of 2,552 people living in 456 households — 1,349 males and 1,203 females, including 348 children aged 0–6. The recorded literacy rate is 58.5 percent. The village is a gram panchayat. Total geographical area is recorded as 428 hectares.$$, 3),\n('culture', 'Culture',\n $$[Information to be added.] Language in daily life is Punjabi. Cultural practices, seasonal festivals, and local customs of Mallu Nangal will be published here only after they are documented by residents and reviewed by the archive.$$, 4),\n('religious-heritage', 'Religious heritage',\n $$[Information to be added.] This archive will list gurdwaras and other places of worship in and around the village, together with verified histories, once families and sevadars have supplied sources. No religious narrative is invented for this page.$$, 5),\n('education', 'Education',\n $$Public school directories record a government primary school at Mallu Nangal (GES / GPS Mallu Nangal, UDISE 03020300601) in Harsha Chhina block, established in 1925 and managed by the Department of Education, with classes 1 to 5. Village census notes also mention government pre-primary, primary, middle and secondary schools in the village. Further school histories, alumni, and photographs are invited through the Contribute page.$$, 6),\n('agriculture', 'Agriculture',\n $$Census village data records 364 hectares of sown land, all irrigated by tube wells, with 64 hectares in non-agricultural use. Wheat, rice and maize are listed as the main crops. A fuller account of holdings, seasons, and change in farming practice will be added from local testimony.$$, 7),\n('community', 'Community',\n $$[Information to be added.] Mallu Nangal is governed as a gram panchayat. Names of current and past sarpanches, societies, sports clubs, and seva groups will be published when they can be documented.$$, 8),\n('places', 'Important places',\n $$[Information to be added.] A map of gurdwaras, schools, ponds, shamlat land, and other landmarks will be compiled with residents. Until then this section is a placeholder.$$, 9)\non conflict (slug) do nothing;\n\ninsert into history_articles (slug, title, excerpt, body, period, period_order, approx_year, image, sources, author, published_at, is_demo) values\n('ancient-period-placeholder', 'Ancient period',\n 'A reserved place on the timeline until archaeology or early sources for this landscape are documented.',\n $$[Information to be added.]\n\nDemo Content — Replace with verified information.\n\nThe Majha countryside around Amritsar has a deep human past, but this archive does not attach Mallu Nangal to any dynasty, battle, or founding legend until a source can be cited. When inscriptions, land records, or oral histories with named informants are received, they will replace this card.$$,\n 'Ancient Period', 1, '[To be added]', '/images/fields.jpg',\n 'Placeholder pending primary sources.', 'Archive editor', '2026-09-16', true),\n('early-settlement-placeholder', 'Early settlement',\n 'How and when the village took its present name is not yet established in this archive.',\n $$[Information to be added.]\n\nDemo Content — Replace with verified information.\n\nThe name Mallu Nangal (Census spelling Malu Nangal) is recorded in modern administrative lists. A careful settlement history — clans, migrations, and the meaning of the name — belongs here only with family genealogies, revenue records, or other cited evidence. Please use Contribute if you hold such papers.$$,\n 'Early Settlement', 2, '[To be added]', '/images/village-lane.jpg',\n 'Placeholder pending village records.', 'Archive editor', '2026-09-16', true),\n('land-and-farming', 'Land and farming',\n 'Census figures describe a fully irrigated agricultural village of wheat, rice and maize.',\n $$Public statistical sources, not local oral history, are the basis of this note.\n\nThe Census of India village abstract for Malu Nangal records a total area of 428 hectares. Of that, 364 hectares are sown and irrigated by boreholes / tube wells; 64 hectares are recorded as non-agricultural. Wheat, rice and maize are listed as the principal crops. Hours of agricultural power supply are noted in some directories as eight hours in summer and ten in winter; that figure should be re-checked with the local electricity record before it is treated as current.\n\nThis article will grow when farmers contribute photographs of fields, wells, and implements, with dates.$$,\n 'Village Development', 3, '2011 record', '/images/fields.jpg',\n 'Census of India 2011 village abstract for Malu Nangal (code 037396); public village directories repeating those figures.', 'Archive editor', '2026-09-16', false),\n('schools-of-the-village', 'Schools of the village',\n 'A government primary school at Mallu Nangal is recorded as opening in 1925.',\n $$Education is one of the few village institutions with a dated public record.\n\nSchool directories list GES / GPS Mallu Nangal (UDISE 03020300601) in Harsha Chhina block, Amritsar district, established in 1925, co-educational, classes 1–5, managed by the Department of Education. Census notes also mention government pre-primary, middle and secondary schools in the village.\n\nThis archive invites photographs of school buildings, staff lists, and alumni memories — dated and attributed — so that a fuller school history can replace this short administrative note.$$,\n 'Important Events', 4, '1925', '/images/school.jpg',\n 'UDISE / public school directory entries for GES Mallu Nangal; Census of India 2011 amenities notes.', 'Archive editor', '2026-09-16', false),\n('census-2011', 'The 2011 census record',\n 'Population, households and literacy as enumerated in the last published census.',\n $$The Census of India 2011 is the most complete published statistical portrait of the village available to this archive.\n\nMalu Nangal (village code 037396) was enumerated with 2,552 residents in 456 households: 1,349 males and 1,203 females. Children aged 0–6 numbered 348. Scheduled Caste population is recorded as 747. Literate population is recorded as 1,493 (literacy rate 58.5 percent in village directory summaries). There is no Scheduled Tribe population in the table.\n\nThese numbers describe one night of enumeration more than a decade ago. They are not a substitute for family histories, and they will be shown beside later counts when those are published.$$,\n 'Modern Period', 5, '2011', '/images/archival-street.jpg',\n 'Census of India 2011, village Malu Nangal, Amritsar district, Punjab.', 'Archive editor', '2026-09-16', false),\n('present-day-setting', 'Mallu Nangal today',\n 'Where the village sits in the Amritsar countryside, and what this archive still needs.',\n $$Mallu Nangal remains a gram panchayat village in Amritsar district, PIN 143101. Public maps place it north of Amritsar city, near Raja Sansi, with Sri Guru Ram Dass Jee International Airport a short aerial distance away. Neighbouring settlements named in directories include Adliwala, Loharka Kalan, Ranewali, Jagdev Kalan and Loharka Khurd.\n\nThis website is being assembled so that residents, not census tables, can tell the rest: gurdwaras, fields, streets, manuscripts, and the people who made the village. Until those contributions are reviewed, many pages will show “[Information to be added]” rather than guesswork.$$,\n 'Present Day', 6, '2026', '/images/hero-village.jpg',\n 'Census of India 2011; GeoNames (Mallu Nangal); public village directories for PIN, neighbours, and tehsil notes.', 'Archive editor', '2026-09-16', false)\non conflict (slug) do nothing;\n\ninsert into history_images (article_id, image, caption, sort_order)\nselect id, '/images/fields.jpg', 'Illustrative farmland photograph — not a surveyed field of Mallu Nangal.', 1\nfrom history_articles where slug = 'land-and-farming'\nand not exists (select 1 from history_images h where h.article_id = history_articles.id);\n\ninsert into history_images (article_id, image, caption, sort_order)\nselect id, '/images/school.jpg', 'Illustrative rural schoolyard — replace with a verified photograph of the village school.', 1\nfrom history_articles where slug = 'schools-of-the-village'\nand not exists (select 1 from history_images h where h.article_id = history_articles.id);\n\ninsert into personalities (slug, name, photograph, birth_date, death_date, profession, education, biography, achievements, contributions, connection, sources, is_demo)\nvalues (\n  'demo-personality-profile',\n  'Demo personality profile',\n  '/images/gurdwara.jpg',\n  '[To be added]',\n  '',\n  '[Profession to be added]',\n  '[To be added]',\n  $$Demo Content — Replace with verified information.\n\nThis card exists so the personalities section has a layout to review. It is not a real biography and must not be read as a person from Mallu Nangal.\n\nWhen a documented life is ready, the archive will publish: a verified name, a dated photograph with photographer or family credit, dates of birth and death, profession, education, a sourced biography, and the person’s connection to the village.$$,\n  '[To be added]',\n  '[To be added]',\n  'Placeholder for a future, sourced biography of a person connected with Mallu Nangal.',\n  'No historical source. Demo layout only.',\n  true\n)\non conflict (slug) do nothing;\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/archive-table.jpg', 'Demo additional photograph — replace with a documented portrait or work.', 1\nfrom personalities where slug = 'demo-personality-profile'\nand not exists (select 1 from personality_photos p where p.personality_id = personalities.id);\n\ninsert into archive_items (\n  item_code, title, author, year_label, period, language, script, material, page_count,\n  category, keywords, description, significance, source_owner, cover_image, references_text, is_demo\n) values\n('MN-MAN-0001', 'Demo manuscript — untitled binding',\n '[Author to be added]', '[Date to be added]', '[Period to be added]',\n '[Language to be added]', '[Script to be added]', '[Material to be added]', 2,\n 'Manuscripts', 'demo, manuscript, placeholder',\n $$Demo Content — Replace with verified information.\n\nCatalogue number MN-MAN-0001 is a working example of how a manuscript will appear in this archive. The cover and leaf photographs are studio and museum-style stand-ins. They are not a real pothi from Mallu Nangal and contain no religious text.\n\nA finished record will include a unique ID, title, author, date or period, language, script, material, page count, description, historical significance, source or owner, and references — entered only from the object itself.$$,\n '[To be added]',\n '[Owner / source to be added]',\n '/images/manuscript-cover.jpg',\n 'Demo object. Not a cited historical manuscript.',\n true),\n('MN-MAN-0002', 'Demo manuscript — second catalogue card',\n '[Author to be added]', '[Date to be added]', '[Period to be added]',\n '[Language to be added]', '[Script to be added]', '[Material to be added]', 0,\n 'Manuscripts', 'demo, manuscript',\n $$Demo Content — Replace with verified information.\n\nMN-MAN-0002 shows a second manuscript card in the library grid. Pages have not been attached. Replace this record with a real catalogue entry when an original is photographed.$$,\n '[To be added]',\n '[Owner / source to be added]',\n '/images/archive-table.jpg',\n 'Demo object.',\n true),\n('MN-DOC-0001', 'Demo historical document',\n '[To be added]', '[To be added]', 'Modern Period',\n 'Punjabi / English', '[To be added]', 'Paper', 0,\n 'Historical Documents', 'demo, document',\n $$Demo Content — Replace with verified information.\n\nThis card stands in for land records, letters, school registers, and other papers. No document has been transcribed here.$$,\n '[To be added]',\n '[To be added]',\n '/images/archival-street.jpg',\n 'Demo record.',\n true),\n('MN-PHO-0001', 'Demo archival photograph',\n 'Unknown photographer', '[To be added]', 'Modern Period',\n '', '', 'Photograph', 1,\n 'Old Photographs', 'demo, photograph, village street',\n $$Demo Content — Replace with verified information.\n\nAn illustrative archival-style photograph used to show how old pictures will be catalogued. It is not identified as a street in Mallu Nangal. Families are invited to send dated prints with names of people and places.$$,\n '[To be added]',\n '[To be added]',\n '/images/archival-street.jpg',\n 'Demo photograph.',\n true),\n('MN-REC-0001', 'Demo village record',\n '[To be added]', '2011', 'Modern Period',\n 'English', 'Latin', 'Digital copy of published statistics', 0,\n 'Village Records', 'census, demo, statistics',\n $$A reminder card pointing to the published Census of India 2011 village tables for Malu Nangal. The census volumes themselves remain the source; this site is not an official census publication.$$,\n 'Published official statistics summarised on the History pages.',\n 'Census of India 2011',\n '/images/fields.jpg',\n 'Census of India 2011, village code 037396.',\n true)\non conflict (item_code) do nothing;\n\ninsert into manuscript_pages (item_id, page_number, image, caption, description)\nselect id, 1, '/images/manuscript-page-01.jpg', 'Demo leaf — not a page of Gurbani or any identified text.',\n 'Placeholder scan for the page viewer. Replace with a high-resolution photograph of the original leaf.'\nfrom archive_items where item_code = 'MN-MAN-0001'\nand not exists (select 1 from manuscript_pages m where m.item_id = archive_items.id and m.page_number = 1);\n\ninsert into manuscript_pages (item_id, page_number, image, caption, description)\nselect id, 2, '/images/manuscript-page-02.jpg', 'Demo leaf two — ornamental stains only, no readable verses.',\n 'Placeholder scan. Zoom and fullscreen in the viewer are for layout testing.'\nfrom archive_items where item_code = 'MN-MAN-0001'\nand not exists (select 1 from manuscript_pages m where m.item_id = archive_items.id and m.page_number = 2);\n\ninsert into hukamnamas (date, ang, title, image, punjabi_text, translation, source, is_demo)\nvalues (\n  '2026-09-16',\n  '[Ang to be added]',\n  'Today''s Hukamnama',\n  '/images/gurdwara.jpg',\n  $$[Information to be added]\n\nThis space is reserved for the verified Punjabi text of the Hukamnama, entered by the archive administrator from a stated source. No Gurbani has been generated or guessed for this website.$$,\n  $$[Information to be added]\n\nTranslation will appear here only when it accompanies a verified text and source. Until then this page is a layout demonstration, not a religious publication.\n\nDemo Content — Replace with verified information.$$,\n  '[Source to be added — for example the gurdwara and date of the hukamnama]',\n  true\n)\non conflict (date) do nothing;\n\ninsert into hukamnamas (date, ang, title, image, punjabi_text, translation, source, is_demo)\nvalues (\n  '2026-09-15',\n  '[Ang to be added]',\n  'Hukamnama archive entry',\n  '/images/gurdwara.jpg',\n  $$[Information to be added] Demo Content — Replace with verified information.$$,\n  $$[Information to be added] A second date so the archive list has more than one row.$$,\n  '[Source to be added]',\n  true\n)\non conflict (date) do nothing;\n\ninsert into galleries (slug, title, description, category, date_label, cover_image, is_demo) values\n('village', 'Village streets and houses',\n 'Demo album of rural Punjab scenes used until identified photographs of Mallu Nangal are received.',\n 'Village', 'Demo album', '/images/village-lane.jpg', true),\n('historical', 'Historical photographs',\n 'A home for dated prints. The current pictures are illustrative, not identified village views.',\n 'Historical', 'Demo album', '/images/archival-street.jpg', true),\n('religious', 'Religious places',\n 'Placeholder views of a village gurdwara. Replace with credited photographs of Mallu Nangal’s own buildings.',\n 'Religious', 'Demo album', '/images/gurdwara.jpg', true),\n('schools', 'Schools',\n 'Illustrative schoolyard until a dated photograph of GES Mallu Nangal is contributed.',\n 'Schools', 'Demo album', '/images/school.jpg', true),\n('agriculture', 'Agriculture',\n 'Fields in the Punjab countryside, standing in for Mallu Nangal farmland still to be photographed.',\n 'Agriculture', 'Demo album', '/images/fields.jpg', true)\non conflict (slug) do nothing;\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/village-lane.jpg', 'Illustrative village lane — not identified as Mallu Nangal.', 'Demo', 1\nfrom galleries where slug = 'village'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/hero-village.jpg', 'Illustrative village edge and fields.', 'Demo', 2\nfrom galleries where slug = 'village'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id and g.sort_order = 2);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/archival-street.jpg', 'Demo archival-style photograph.', 'Demo', 1\nfrom galleries where slug = 'historical'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/gurdwara.jpg', 'Illustrative village gurdwara — identity to be confirmed.', 'Demo', 1\nfrom galleries where slug = 'religious'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/school.jpg', 'Illustrative rural school.', 'Demo', 1\nfrom galleries where slug = 'schools'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/fields.jpg', 'Illustrative irrigated fields.', 'Demo', 1\nfrom galleries where slug = 'agriculture'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/hero-village.jpg', 'Illustrative wheat landscape.', 'Demo', 2\nfrom galleries where slug = 'agriculture'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id and g.sort_order = 2);\n\ninsert into videos (title, description, youtube_url, thumbnail, event_date, category, duration, is_demo) values\n('Village event recording — to be added',\n 'Demo Content — Replace with a YouTube link to a verified recording from Mallu Nangal. This card shows how events will appear in the archive.',\n '', '/images/hero-village.jpg', null, 'Village Events', '', true),\n('Religious occasion — to be added',\n 'Demo Content — Replace with a credited recording. No religious video has been published yet.',\n '', '/images/gurdwara.jpg', null, 'Religious Events', '', true),\n('Fields and seasons — to be added',\n 'Demo Content — A place for documentaries and interviews once they are uploaded to YouTube and reviewed.',\n '', '/images/fields.jpg', null, 'Documentaries', '', true);\n\ninsert into live_events (title, description, event_date, location, youtube_url, thumbnail, is_live, start_time, end_time, is_demo)\nvalues (\n  'Next village gathering',\n  'When a live stream is arranged, an administrator will paste the YouTube Live address and mark the event as live. Until then this page stays quiet.',\n  null,\n  'Mallu Nangal',\n  '',\n  '/images/gurdwara.jpg',\n  false,\n  '',\n  '',\n  true\n);\n\ninsert into news (slug, title, excerpt, body, image, author, published_at, category, is_demo) values\n('a-digital-archive-opens', 'A digital archive for Mallu Nangal',\n 'This website is being built as a public home for the village’s documents, photographs, and memory.',\n $$The pages you are reading are the beginning of a village archive, not a finished history book.\n\nWhat is already on record — census figures, the location of the village, the 1925 primary school — is cited. What is not yet documented is left open. Families are asked to contribute old photographs, manuscripts, and named memories through the Contribute page. Nothing sent there is published until it has been reviewed.\n\nDemo layout photographs on several pages are labelled as such and will be replaced by pictures taken in Mallu Nangal.$$,\n '/images/archive-table.jpg', 'Archive editor', '2026-09-16', 'Archive', false),\n('share-old-photographs', 'Share old photographs and family papers',\n 'Prints, pothis, school records and oral histories can be offered to the archive for review.',\n $$If you have a photograph of a street, a wedding, a field, a school class, or an elder, or if you hold a manuscript or land paper connected with Mallu Nangal, you can describe it on the Contribute page.\n\nPlease do not send the only original of a manuscript through an untrusted channel. Note what you have; the archive can arrange a safer copy. Submissions stay in a review queue and are not shown on the public site automatically.$$,\n '/images/archival-street.jpg', 'Archive editor', '2026-09-12', 'Appeal', false)\non conflict (slug) do nothing;\n";
var _0004_inbox_default = "alter table contributions add column if not exists sender_name text not null default '';\nalter table contributions add column if not exists sender_email text not null default '';\nalter table contributions add column if not exists sender_phone text not null default '';\n\nalter table contact_messages add column if not exists sender_name text not null default '';\nalter table contact_messages add column if not exists sender_email text not null default '';\nalter table contact_messages add column if not exists sender_phone text not null default '';\n\ninsert into galleries (slug, title, description, category, date_label, cover_image, is_demo) values\n('people', 'People of the village',\n 'Portraits will be published with names, dates and family credit. This album is a layout study until those prints arrive.',\n 'People', 'Demo album', '/images/courtyard.jpg', true),\n('events', 'Village events',\n 'Weddings, gatherings and public occasions — labelled when photographs can be dated and identified.',\n 'Events', 'Demo album', '/images/gurdwara.jpg', true),\n('old-photographs', 'Old photographs',\n 'A drawer for prints that predate colour film. Current pictures are illustrative, not identified streets.',\n 'Old Photographs', 'Demo album', '/images/archival-street.jpg', true),\n('festivals', 'Festivals',\n 'Seasonal and religious festivals of Mallu Nangal will be filed here once residents contribute dated photographs.',\n 'Festivals', 'Demo album', '/images/phulkari.jpg', true),\n('village-development', 'Village development',\n 'Roads, ponds, schools and new building. Placeholder landscapes until survey photographs are offered.',\n 'Village Development', 'Demo album', '/images/mustard-fields.jpg', true)\non conflict (slug) do nothing;\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/courtyard.jpg', 'Illustrative courtyard — not identified as a house in Mallu Nangal.', 'Demo', 1\nfrom galleries where slug = 'people'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/phulkari.jpg', 'Phulkari textile study for festival colour — not a dated village object.', 'Demo', 1\nfrom galleries where slug = 'festivals'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/mustard-fields.jpg', 'Illustrative mustard fields of the Majha countryside.', 'Demo', 1\nfrom galleries where slug = 'village-development'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/archival-street.jpg', 'Demo archival-style print.', 'Demo', 1\nfrom galleries where slug = 'old-photographs'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\ninsert into gallery_images (gallery_id, image, caption, date_label, sort_order)\nselect id, '/images/gurdwara.jpg', 'Illustrative gathering place — identity to be confirmed.', 'Demo', 1\nfrom galleries where slug = 'events'\nand not exists (select 1 from gallery_images g where g.gallery_id = galleries.id);\n\nupdate personalities\nset photograph = '/images/courtyard.jpg'\nwhere slug = 'demo-personality-profile' and is_demo = true;\n";
var _0005_punjabi_name_default = "update about_sections\nset body = $$Mallu Nangal (Punjabi: ਮੱਲੂ ਨੰਗਲ) is a village in Amritsar district, Punjab, India. In official Census of India records the settlement is also spelled Malu Nangal. This website is a public archive for the village’s history, families, religious life, photographs, and documents. Where a fact has not yet been verified by the archive, it is left blank or clearly marked as demo layout content.$$\nwhere slug = 'introduction';\n\nupdate history_articles\nset body = $$[Information to be added.]\n\nDemo Content — Replace with verified information.\n\nThe name Mallu Nangal (Punjabi: ਮੱਲੂ ਨੰਗਲ; Census spelling Malu Nangal) is recorded in modern administrative lists. A careful settlement history — clans, migrations, and the meaning of the name — belongs here only with family genealogies, revenue records, or other cited evidence. Please use Contribute if you hold such papers.$$\nwhere slug = 'early-settlement-placeholder';\n";
var _0006_guru_arjan_tradition_default = "update history_articles\nset\n  title = 'A tradition of Guru Arjan Dev Ji',\n  excerpt = 'Two published tellings connect ਮੱਲੂ ਨੰਗਲ with Guru Arjan and a Sikh remembered as Mallu. They do not agree, and neither is a contemporary record.',\n  approx_year = 'Undated; Guru Arjan’s years are 1581–1606',\n  image = '/images/gurdwara.jpg',\n  is_demo = false,\n  author = 'Archive editor',\n  updated_at = '2026-10-14',\n  sources = 'Punjab Kosh, vol. 2 (Language Department, Punjab), as reprinted on Punjabi Pedia, citing Ajit, 7 August 1992, and the 1981 Amritsar district handbook. Second telling: an online account of Gurdwara Shri Guru Arjan Dev Ji Sahib, Mallu Nangal, attributed to HistoricalGurudwaras.com and copied into this archive on 14 October 2026; that page could not be re-opened here. Nearby shrine, not this village: Kahn Singh / Encyclopaedia of Sikhism, “Ghukkevali”; Discover Sikhism, Gurdwara Sri Guru Ka Bagh Ghukeywali. Guru Arjan’s life: standard Sikh chronology (birth 1563, guruship 1581–1606, death in Mughal custody at Lahore, 1606).',\n  body = $trad$This card keeps two things apart. The life of Sri Guru Arjan Dev Ji is documented well beyond this village. A halt at ਮੱਲੂ ਨੰਗਲ is local tradition. The two written versions of that tradition do not match, so they are printed side by side and not stitched into one story.\n\nSri Guru Arjan Dev Ji (1563–1606) was the fifth Sikh Guru, from 1581 until his death in Mughal custody at Lahore in 1606. In those years the sarovar and Harmandir Sahib at Amritsar were completed, and the Adi Granth was compiled and installed there in 1604. Those facts belong to Sikh history at large. They are not, by themselves, proof that he stopped in this village.\n\nPunjab Kosh, volume 2, records one sakhi. Gurdwara Mallu Nangal Sahib stands outside the village, on the road from Amritsar toward Jagdev Kalan. The village is placed in Ajnala tehsil, about ten kilometres from Majitha. The Kosh says that Guru Arjan, travelling toward Guru Ke Bagh with devotees, rested here and asked for water. A servant drew it from a nearby well in a clay pot. A Pathan of the settlement then called Lille broke the pot, the water spilled, and the Guru remained thirsty. The earlier name of the place, in this telling, was Lille. The Guru is quoted as saying: “ਜਾਣਗੇ ਲਿੱਲੇ, ਆਉਣਗੇ ਗਿੱਲੇ” — the Lille will go; the Gills will come. A Gursikh named Mallu Gill, grazing buffaloes outside the village, gathered about twenty to twenty-five Sikhs that same night. The Pathans left. In the morning, pleased, the Guru named the village ਮੱਲੂ ਨੰਗਲ after Mallu. The Kosh adds that most residents are of the Gill got, and describes a white-marble gurdwara, a tall Nishan Sahib, a small library, rooms for visitors, Gurpurab and Sangrand gatherings, and langar. Its population figure, 1,752, is the 1981 count, not the 2011 census.\n\nA second telling was supplied to this archive from an online directory, HistoricalGurudwaras.com, under Gurdwara Shri Guru Arjan Dev Ji Sahib, Mallu Nangal. The archive could not re-open that page, so this version is filed as received. In it the earlier settlement is Kho Nangal, associated with Pathans called the Lile. Guru Arjan is said to have been travelling toward Guru Ka Bagh, accompanied by Raja Hari Sen of Suket. Sikhs were sent to a well for water; local Pathans damaged the pitcher and spoke disrespectfully; the Guru went on. Bhai Mallu Ji is placed at Jagdev Kalan, not in the herd outside Lille. After the incident he is said to have attacked and destroyed the older settlement and founded a new one, called Malu Nangal after him, with the Guru’s blessings. That account does not produce a contemporary writing in which Guru Arjan ordered the attack, and it gives no year.\n\nThe two tellings cannot both be exact. One earlier name is Lille; the other is Kho Nangal. One Mallu is a Gill already at the place, who acts the same night; the other comes from Jagdev Kalan and founds a new village afterwards. Until an older manuscript, a revenue spelling, or a named village witness is filed, this archive will not choose between them and will not assign a year.\n\nA related shrine is documented nearby, and should not be confused with this village. Gurdwara Guru Ka Bagh at Ghukkevali (also spelled Ghukeywali), in Ajnala tahsil, about twelve kilometres east of Ajnala and about twenty kilometres from Amritsar, is recorded as a place where Guru Arjan stayed while travelling in the Majha. A sakhi told there concerns Raja Hari Sen of Suket, who came to the Guru at Amritsar and later returned with him to Guru Ka Bagh. Guru Tegh Bahadur is also associated with that garden, in 1664. Those pages do not name ਮੱਲੂ ਨੰਗਲ. They do show why a local memory of a journey “toward Guru Ka Bagh”, and of Raja Hari Sen, can arise in this countryside.\n\nBhai Mallu of this sakhi is not Bhai Mallu Saahi, a Sikh remembered from the time of Guru Angad. No published source found for this archive places Guru Nanak, Guru Hargobind, Guru Tegh Bahadur, or Guru Gobind Singh in ਮੱਲੂ ਨੰਗਲ itself.\n\nWhat would settle more of this: the Granthi and the gurdwara committee’s own sakhi, in Punjabi, with the wording they use; any inscription or foundation date; older spellings in revenue papers and maps; and a genealogy for Mallu that can be checked against Jagdev Kalan. Those papers are invited on the Contribute page. The website is not the only copy that should exist.$trad$\nwhere slug = 'early-settlement-placeholder';\n\nupdate about_sections\nset body = $trad$A local tradition, preserved in more than one written form, connects ਮੱਲੂ ਨੰਗਲ with Sri Guru Arjan Dev Ji and a Sikh remembered as Mallu or Bhai Mallu Ji. Punjab Kosh and a gurdwara-directory account do not agree on the earlier name of the settlement or on who Mallu was. Both are filed on the History page as tradition, not as a dated record. No year is assigned.\n\nGurdwara Mallu Nangal Sahib is described in Punjab Kosh as standing outside the village on the road toward Jagdev Kalan. This archive does not yet hold a photograph of that building, an inscription, or a foundation date. Families and the gurdwara committee are invited to supply those.\n\nThe documented life of Guru Arjan — Harmandir Sahib, the Adi Granth, and his death at Lahore in 1606 — is Sikh history of the region. It is not, by itself, proof of a halt in this village. Nearby, Gurdwara Guru Ka Bagh at Ghukkevali in Ajnala tahsil is a separate shrine associated with Guru Arjan and, later, Guru Tegh Bahadur. It is not this village’s gurdwara.$trad$\nwhere slug = 'religious-heritage';\n";
var _0007_brief_history_default = "insert into history_articles (\n  slug, title, excerpt, body, period, period_order, approx_year, image, sources, author, published_at, updated_at, is_demo\n) values (\n  'brief-history',\n  'A brief history of ਮੱਲੂ ਨੰਗਲ',\n  'Every fact this archive can currently cite: place, name, the Guru Arjan tradition, census, land, school, and the gurdwara account.',\n  $brief$ਮੱਲੂ ਨੰਗਲ (also spelled Mallu Nangal, and Malu Nangal in the Census of India) is a gram panchayat village in the Majha region of Amritsar district, Punjab. The PIN code is 143101. The postal head office is Raja Sansi. Directories place it in Ajnala tehsil and the Harsha Chhina (Harsa Chhina) block; some also name Lopoke tehsil. It falls in the Amritsar assembly constituency and the Amritsar Lok Sabha constituency, and is headed by an elected sarpanch. GeoNames lists the place at about 31.75° N, 74.85° E, roughly 230 metres above sea level.\n\nDistances vary by the directory that prints them, so they are given as printed. One places the village about 13 kilometres north of Amritsar city and about 9 kilometres from Harsha Chhina. Another says about 18 kilometres from Ajnala and about 18 kilometres from Amritsar. Punjab Kosh says about 10 kilometres from Majitha. Raja Sansi is the nearest town, about 5 kilometres away. Neighbours named in directories are Adliwala and Loharka Kalan (about 2 kilometres), Ranewali (about 2 kilometres), Jagdev Kalan (about 3 kilometres), and Loharka Khurd (about 4 kilometres). An all-weather road and bus service are recorded. The nearest railway station named in one directory is Verka Junction. Sri Guru Ram Dass Jee International Airport is about 6 kilometres away by air. The same directory names the Ravi and the Kiran Saiki nala as waters in the wider area, not as streams inside the village.\n\nHow the village got its name is tradition, not a dated land record, and two published tellings disagree.\n\nPunjab Kosh, volume 2, says the older name was Lille. Guru Arjan Dev Ji, travelling toward Guru Ke Bagh, stopped and asked for water. A servant drew it from a well in a clay pot. A Pathan of Lille broke the pot. The Guru is quoted: “ਜਾਣਗੇ ਲਿੱਲੇ, ਆਉਣਗੇ ਗਿੱਲੇ” — the Lille will go; the Gills will come. Mallu Gill, grazing buffaloes outside, gathered about twenty to twenty-five Sikhs that night. The Pathans left. In the morning the Guru named the village ਮੱਲੂ ਨੰਗਲ. The Kosh says most residents are of the Gill got.\n\nA second account, filed from a gurdwara directory (HistoricalGurudwaras.com) and not re-opened page by page, says the older name was Kho Nangal and the people were Lile Pathans. Guru Arjan was travelling toward Guru Ka Bagh with Raja Hari Sen of Suket. Pathans damaged the water pitcher. Bhai Mallu Ji of Jagdev Kalan later destroyed that settlement and founded a new one called Malu Nangal, with the Guru’s blessings. That account does not show a writing in which the Guru ordered the attack, and it gives no year.\n\nNo year is assigned. No source found here places Guru Nanak, Guru Hargobind, Guru Tegh Bahadur, or Guru Gobind Singh in this village. Bhai Mallu of the sakhi is not Bhai Mallu Saahi of Guru Angad’s time. Nearby, but separate, Gurdwara Guru Ka Bagh at Ghukkevali in Ajnala tahsil is recorded as a stay of Guru Arjan in the Majha and as the place of the Raja Hari Sen sakhi; Guru Tegh Bahadur is associated with that garden in 1664. Those pages do not name ਮੱਲੂ ਨੰਗਲ.\n\nGuru Arjan’s own life is documented apart from the village: born 1563, Guru from 1581 to 1606, Harmandir Sahib completed and the Adi Granth installed at Amritsar in 1604, death in Mughal custody at Lahore in 1606.\n\nPunjab Kosh describes Gurdwara Mallu Nangal Sahib outside the village on the road from Amritsar toward Jagdev Kalan: a white-marble building, khandas on the domes, a Nishan Sahib of about 105 feet, a small Sikh-history library, twelve rooms for visitors, Gurpurabs, Sangrand gatherings, and langar, looked after by a local gurdwara committee. This archive does not yet hold a photograph, an inscription, or a foundation date for that building.\n\nAn editable public directory adds an unsourced note that an Ansari Muslim family and a mosque were here, and that the family left for Pakistan at Partition. That note can be changed by anyone. It is recorded only as a lead, not as established history.\n\nThe earliest population figure in these sources is 1,752 in 1981, printed in Punjab Kosh.\n\nThe Census of India 2011 (village code 037396) counted 2,552 people in 456 households: 1,349 males and 1,203 females. Children aged 0–6 numbered 348 (201 boys and 147 girls). Scheduled Caste population was 747 (376 males and 371 females). Scheduled Tribe population was 0. Literate people numbered 1,493 (838 males and 655 females); illiterate people numbered 1,059. Directory summaries give the literacy rate as 58.5 percent. The village area was 428 hectares. Of that, 364 hectares were sown and irrigated by tube wells, and 64 hectares were non-agricultural. Wheat, rice, and maize are the crops named. One directory’s note of eight hours of farm power in summer and ten in winter should be checked against the electricity record before it is treated as current.\n\nA government primary school, GES / GPS Mallu Nangal (UDISE 03020300601), in Harsha Chhina block, is recorded as opening in 1925. It is co-educational, classes 1 to 5, under the Department of Education. Census notes also mention government pre-primary, middle, and secondary schooling in the village. A government high school, GHS Mallu Nangal, is listed, and a private primary school, Sri Guru Arjun Dev Model School. The “Mallu Nangal” school cluster covers about twenty-one schools in the surrounding villages; those are not all inside this village.\n\nWhat is still missing, and is not invented here: the year the village was founded, which of the two name-stories is older, Mallu’s father’s name and lineage, a photograph of the gurdwara, family papers, and any hukamnama or manuscript that actually belongs to ਮੱਲੂ ਨੰਗਲ. Those belong on the Contribute page, with a date and a source.$brief$,\n  'Brief history',\n  0,\n  'Recorded facts to 2011',\n  '/images/mustard-fields.jpg',\n  'Census of India 2011, village Malu Nangal (code 037396). Punjab Kosh, vol. 2, via Punjabi Pedia (Ajit, 7 August 1992; 1981 Amritsar handbook). UDISE / school directories for GPS and GHS Mallu Nangal. Public village directories for PIN 143101, neighbours, tehsil, airport, and the unverified Partition note. Encyclopaedia of Sikhism and Discover Sikhism for Gurdwara Guru Ka Bagh, Ghukkevali — a different village. HistoricalGurudwaras.com account of this village as supplied to the archive on 14 October 2026.',\n  'Archive editor',\n  '2026-10-14',\n  '2026-10-14',\n  false\n)\non conflict (slug) do nothing;\n";
var _0008_history_text_default = "update history_articles\nset\n  title = 'History of ਮੱਲੂ ਨੰਗਲ',\n  excerpt = 'A traditional connection with Sri Guru Arjan Dev Ji and Bhai Mallu Ji. Two written accounts are kept side by side, and neither is treated as a dated chronology.',\n  approx_year = 'Tradition — visit undated',\n  image = '/images/gurdwara.jpg',\n  is_demo = false,\n  author = 'Archive editor',\n  updated_at = '2026-10-16',\n  sources = 'Punjab Kosh, Volume II, Language Department, Punjab, as reproduced by Punjabi Pedia. HistoricalGurudwaras.com, account of Gurdwara Sri Guru Arjan Dev Ji Sahib, Malu Nangal, as supplied to this archive.',\n  body = $hist$## 1. Introduction\n\nMallu Nangal (ਮੱਲੂ ਨੰਗਲ), also spelled Malu Nangal in official records, is a village in Amritsar district, Punjab, in the Majha region. The village is associated with a local historical tradition connecting Sri Guru Arjan Dev Ji, the fifth Sikh Guru, with Bhai Mallu Ji, whose name is traditionally linked to the village’s present name.\n\nThe principal written accounts of this tradition appear in Punjab Kosh, published by the Language Department of Punjab, and in an online record of Gurdwara Sri Guru Arjan Dev Ji Sahib at Mallu Nangal.\n\nThese accounts preserve the village’s religious heritage but differ on the earlier name of the settlement and the events surrounding its establishment. The story of the village’s origin is therefore a traditional historical account, not a fully verified chronology.\n\n## 2. The traditional connection with Sri Guru Arjan Dev Ji\n\nAccording to Punjab Kosh, Sri Guru Arjan Dev Ji visited the area while travelling towards Guru Ke Bagh. During this journey, Guru Sahib is said to have stopped briefly and requested water.\n\nThe account relates that a Sikh attendant drew water from a nearby well in an earthen vessel. A Pathan from the settlement broke the vessel, leaving Guru Sahib without water.\n\nThe account attributes the following words to Guru Sahib:\n\n“ਜਾਣਗੇ ਲਿੱਲੇ, ਆਉਣਗੇ ਗਿੱਲੇ.”\n\nThe traditional narrative associates these words with the subsequent departure of the earlier inhabitants and the emergence of the settlement known as Mallu Nangal.\n\nA separate account published by HistoricalGurudwaras.com also describes Guru Arjan Dev Ji’s visit while travelling towards Guru Ke Bagh. It adds that Raja Hari Sen of Suket Mandi accompanied Guru Sahib.\n\nAlthough both accounts describe an incident involving water and a broken vessel, they differ in other details. The available sources do not establish the exact date of the visit, and they do not independently verify every element of the story.\n\n## 3. Bhai Mallu Ji and the origin of the village’s name\n\nBhai Mallu Ji occupies an important place in the traditional history of Mallu Nangal. The two available accounts describe his role differently.\n\nAccording to Punjab Kosh, a Sikh named Mallu Gill was grazing buffaloes outside the settlement. Upon learning about the incident involving Guru Sahib, he gathered approximately 20–25 Sikhs and attacked the Pathans during the night. The account states that the Pathans subsequently left the settlement, and that Guru Sahib later named the village Mallu Nangal in recognition of Mallu’s actions.\n\nThe separate Gurdwara account identifies Bhai Malu Ji as a resident of Jagdev Kalan. It states that he later attacked and destroyed the earlier settlement and established a new village that became known as Malu Nangal.\n\nBoth accounts associate the village’s name with Mallu or Malu. They differ in their descriptions of the earlier settlement and in the circumstances in which the new village was established.\n\nThe available sources do not independently establish Bhai Mallu Ji’s birth date, family lineage, father’s name, or the precise date of the settlement’s foundation. Those details remain open to further investigation.\n\n## 4. Gurdwara Sri Guru Arjan Dev Ji Sahib\n\nGurdwara Sri Guru Arjan Dev Ji Sahib is the religious landmark associated with the traditional account of Guru Sahib’s visit to Mallu Nangal.\n\nThe Punjab Kosh entry describes the Gurdwara as standing outside the village, on the road towards Jagdev Kalan. It records a white-marble building, domes bearing Khanda symbols, a Nishan Sahib approximately 105 feet high, a library relating to Sikh history, and twelve rooms for visitors.\n\nThe same account mentions the observance of Gurpurabs, Sangrand gatherings, and the serving of langar.\n\nThese details document the Gurdwara’s religious and community significance as described in the published entry. The exact date of its original construction, and the earliest surviving documentary record of the shrine, have not been established by the sources examined.\n\nThe Gurdwara and its management committee may hold further information about its development, its historical traditions, and its past custodians.$hist$\nwhere slug = 'brief-history';\n\nupdate history_articles\nset\n  title = 'Two accounts of the village name',\n  excerpt = 'Punjab Kosh and the Gurdwara account do not agree on the earlier name, or on who Bhai Mallu Ji was. The full telling is in History of ਮੱਲੂ ਨੰਗਲ.',\n  body = $hist$The full traditional history is set out in “History of ਮੱਲੂ ਨੰਗਲ”, the first record on this timeline. This note only keeps the points on which the two written accounts differ, so they are not blended into one story.\n\nPunjab Kosh says the earlier settlement was associated with Pathans of Lille. Guru Arjan Dev Ji, travelling towards Guru Ke Bagh, asked for water. An attendant drew it in an earthen vessel. A Pathan broke the vessel. The Guru is quoted: “ਜਾਣਗੇ ਲਿੱਲੇ, ਆਉਣਗੇ ਗਿੱਲੇ.” Mallu Gill, grazing buffaloes outside, gathered about 20–25 Sikhs that night. The Pathans left. Guru Sahib then named the village Mallu Nangal.\n\nThe Gurdwara account on HistoricalGurudwaras.com says Guru Sahib was travelling towards Guru Ke Bagh with Raja Hari Sen of Suket Mandi. It identifies Bhai Malu Ji as a resident of Jagdev Kalan, who later destroyed the earlier settlement and established the village known as Malu Nangal.\n\nNeither account gives a year. Neither gives Bhai Mallu Ji’s father’s name, lineage, or date of birth. The visit is tradition, not a verified chronology.$hist$,\n  sources = 'Punjab Kosh, Volume II, Language Department, Punjab, via Punjabi Pedia. HistoricalGurudwaras.com account of Gurdwara Sri Guru Arjan Dev Ji Sahib, Malu Nangal.',\n  updated_at = '2026-10-16',\n  is_demo = false\nwhere slug = 'early-settlement-placeholder';\n\nupdate about_sections\nset body = $hist$A local tradition connects ਮੱਲੂ ਨੰਗਲ with Sri Guru Arjan Dev Ji and with Bhai Mallu Ji, whose name is traditionally linked to the village. Punjab Kosh and an online account of Gurdwara Sri Guru Arjan Dev Ji Sahib both describe a visit while Guru Sahib was travelling towards Guru Ke Bagh, and an incident with a broken water vessel. They do not agree on the earlier name of the settlement or on whether Mallu was Mallu Gill, already at the place, or Bhai Malu Ji of Jagdev Kalan. No year is known. The full account is on the History page.\n\nPunjab Kosh describes the Gurdwara as standing outside the village on the road towards Jagdev Kalan: white marble, Khanda emblems on the domes, a Nishan Sahib of about 105 feet, a small library, twelve rooms for visitors, Gurpurabs, Sangrand gatherings, and langar. This archive does not yet hold a photograph, an inscription, or a foundation date.$hist$\nwhere slug = 'religious-heritage';\n";
var _0009_history_image_default = "update history_articles\nset image = '/images/mustard-fields.jpg'\nwhere slug = 'brief-history';\n";
var _0010_about_known_default = "update about_sections\nset body = $about$Mallu Nangal (ਮੱਲੂ ਨੰਗਲ) is a gram panchayat village in the Majha region of Amritsar district, Punjab. Official Census records also spell the name Malu Nangal. This website is a public archive for the village’s history, families, religious life, photographs, and documents.\n\nA local tradition connects the name with Sri Guru Arjan Dev Ji and Bhai Mallu Ji. Punjab Kosh and an account of Gurdwara Sri Guru Arjan Dev Ji Sahib both preserve that memory, and they do not agree on every detail. The History page prints both accounts and does not assign a year. Facts that are not yet documented are left open, or marked when a page is only a layout.$about$\nwhere slug = 'introduction';\n\nupdate about_sections\nset body = $about$Punjabi is the language of daily life, written in Gurmukhi as ਮੱਲੂ ਨੰਗਲ. Punjab Kosh records that most residents are of the Gill got. That is a published note about the village, not a count of every household.\n\nThe same entry says the gurdwara observes Gurpurabs and Sangrand, and serves langar. Weddings, seasonal fairs, and other local customs are not written down here yet. They will be added only from residents, with a name and a date.$about$\nwhere slug = 'culture';\n\nupdate about_sections\nset body = $about$The village is a gram panchayat, headed by an elected sarpanch. Punjab Kosh says Gurdwara Sri Guru Arjan Dev Ji Sahib is looked after by a local gurdwara committee, not that a list of its members has been published.\n\nNames of sarpanches, societies, sports clubs, and seva groups are not in this archive. They will be added when a resident or a record can be cited.$about$\nwhere slug = 'community';\n\nupdate about_sections\nset body = $about$Places that can be named from published sources:\n\nGurdwara Sri Guru Arjan Dev Ji Sahib stands, according to Punjab Kosh, outside the village on the road toward Jagdev Kalan. The entry describes white marble, Khanda emblems on the domes, a Nishan Sahib of about 105 feet, a small library, and twelve rooms for visitors. This archive has no photograph and no foundation date.\n\nThe government primary school, GPS Mallu Nangal, is recorded as opening in 1925. Directories also list a government high school and a private primary, Sri Guru Arjun Dev Model School.\n\nRaja Sansi, about five kilometres away, is the nearest town and the post office for PIN 143101. Neighbouring villages named in directories are Adliwala, Loharka Kalan, Ranewali, Jagdev Kalan, and Loharka Khurd.\n\nA drawn map of ponds, shamlat land, and streets has not been compiled.$about$\nwhere slug = 'places';\n";
var _0011_jathedar_dalip_singh_default = "insert into personalities (\n  slug, name, photograph, birth_date, death_date, profession, education,\n  biography, achievements, contributions, connection, sources, is_demo\n) values (\n  'jathedar-dalip-singh',\n  'Jathedar Dalip Singh Ji',\n  '/images/phulkari.jpg',\n  'Not yet recorded',\n  '',\n  'Jathedar',\n  'Not yet recorded',\n  $bio$Jathedar Dalip Singh Ji (ਜਥੇਦਾਰ ਦਲੀਪ ਸਿੰਘ ਜੀ) is entered here as a personality of ਮੱਲੂ ਨੰਗਲ at the village archive’s own request.\n\nA published life of a Jathedar of this name, tied to this village, was not found in the sources checked. Birth, death, family, and the offices he held are therefore left blank. They will be added when the family or a written record supplies them.\n\nHe is not identified on this page with Maharaja Dalip Singh, with Jathedar Dalip Singh Talwandi, or with any other published Dalip Singh. Those are different people.$bio$,\n  $bio$Not yet recorded. Achievements will be added only from a named source.$bio$,\n  $bio$Not yet recorded.$bio$,\n  $bio$The village archive has asked that Jathedar Dalip Singh Ji be listed among the people of ਮੱਲੂ ਨੰਗਲ. The nature of that connection — birth, seva, or residence — has not yet been written down.$bio$,\n  'Name supplied by the village archive, 16 October 2026. No published biography of a Jathedar Dalip Singh of Mallu Nangal was located.',\n  false\n)\non conflict (slug) do nothing;\n";
var _0012_dalip_singh_photos_default = "update personalities\nset\n  photograph = '/images/jathedar-dalip-singh-portrait.jpg',\n  sources = 'Name and photographs supplied by the village archive, October 2026. No published biography of a Jathedar Dalip Singh of Mallu Nangal was located. The portrait carries a studio mark; it is not treated here as a verified date.'\nwhere slug = 'jathedar-dalip-singh';\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/jathedar-dalip-singh-portrait.jpg',\n  'Portrait of Jathedar Dalip Singh Ji, supplied for this archive. A studio mark in the corner appears to name Amritsar.',\n  1\nfrom personalities\nwhere slug = 'jathedar-dalip-singh'\nand not exists (\n  select 1 from personality_photos p\n  where p.personality_id = personalities.id\n    and p.image = '/images/jathedar-dalip-singh-portrait.jpg'\n);\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/jathedar-dalip-singh-reading.jpg',\n  'Jathedar Dalip Singh Ji reading a pothi. Photograph supplied for this archive.',\n  2\nfrom personalities\nwhere slug = 'jathedar-dalip-singh'\nand not exists (\n  select 1 from personality_photos p\n  where p.personality_id = personalities.id\n    and p.image = '/images/jathedar-dalip-singh-reading.jpg'\n);\n";
var _0013_dalip_singh_face_default = "update personalities\nset photograph = '/images/jathedar-dalip-singh-face.jpg'\nwhere slug = 'jathedar-dalip-singh';\n";
var _0014_dalip_singh_citation_default = "update personalities\nset\n  birth_date = '2 February 1931',\n  death_date = '',\n  profession = 'Jathedar',\n  education = 'Village primary school, the school at Jagdev Kalan, and Khalsa School at Guru Ke Bagh; matriculation, then study of religious texts.',\n  biography = $bio$## ਸਨਮਾਨ-ਪੱਤਰ\n\nਜੀ\nਸ੍ਰ: ਦਲੀਪ ਸਿੰਘ ਜੀ ਮੱਲੂ ਨੰਗਲ\nਨੂੰ\nਅੰਮ੍ਰਿਤਸਰ ਨਗਰ ਨਿਵਾਸੀਆਂ ਵੱਲੋਂ ਸਥਾਪਤ\n“ਵਿਸ਼ੇਸ਼ ਸੇਵਾ ਅਵਾਰਡ”\nਨਾਲ ਸਨਮਾਨਿਤ ਕੀਤੇ ਜਾਣ ਦੇ ਮੌਕੇ ਤੇ ਪੜ੍ਹਿਆ ਗਿਆ।\n\nਕਰਤੱਵ ਹੀ ਮਨੁੱਖੀ ਸ਼ਖ਼ਸੀਅਤ ਦੀ ਜਾਣ ਪਛਾਣ ਹੈ ਅਤੇ ਜਦੋਂ ਕਰਤੱਵ ਨਿਸ਼ਕਾਮ ਹੋਣ ਤਾਂ ਸ਼ਖ਼ਸੀਅਤ ਉੱਪਰ ਨਿਖਾਰ ਆ ਜਾਣਾ ਕੁਦਰਤੀ ਹੈ। ਸਰਦਾਰ ਦਲੀਪ ਸਿੰਘ ਮੱਲੂ ਨੰਗਲ ਅਜਿਹੇ ਦਰਵੇਸ਼ ਆਗੂ ਹਨ ਜਿਨ੍ਹਾਂ ਦਾ ਜੀਵਨ ਤੇ ਕੰਮ ਅੱਜਕੱਲ੍ਹ ਦੇ ਸਾਰੇ ਆਗੂਆਂ ਲਈ ਇੱਕ ਮਿਸਾਲ ਹੈ।\n\n2 ਫਰਵਰੀ 1931 ਨੂੰ ਅੰਮ੍ਰਿਤਸਰ ਸ਼ਹਿਰ ਤੋਂ ਕੇਵਲ 13 ਕਿਲੋਮੀਟਰ ਦੀ ਦੂਰੀ ਤੇ ਸਥਿਤ ਪਿੰਡ ਮੱਲੂ ਨੰਗਲ ਵਿਖੇ ਜਨਮੇ ਸ੍ਰ: ਦਲੀਪ ਸਿੰਘ ਮੱਲੂ ਨੰਗਲ ਨੇ ਆਪਣੀ ਮੁੱਢਲੀ ਵਿੱਦਿਆ ਪਿੰਡ ਦੇ ਪ੍ਰਾਇਮਰੀ ਸਕੂਲ, ਨੇੜਲੇ ਜਗਦੇਵ ਕਲਾਂ ਦੇ ਸਕੂਲ ਅਤੇ ਗੁਰੂ ਕੇ ਬਾਗ਼ ਵਿਖੇ ਸਥਿਤ ਖ਼ਾਲਸਾ ਸਕੂਲ ਤੋਂ ਪ੍ਰਾਪਤ ਕੀਤੀ।\n\nਸ੍ਰ: ਦਲੀਪ ਸਿੰਘ ਦਾ ਪਰਿਵਾਰ ਸ਼ੁਰੂ ਤੋਂ ਹੀ ਧਾਰਮਿਕ ਰੁਚੀਆਂ ਵਾਲਾ ਪਰਿਵਾਰ ਸੀ ਅਤੇ ਅਜਿਹੀ ਹੀ ਲਗਨ ਆਪ ਜੀ ਨੂੰ ਪਿਤਾ-ਪੁਰਖੀ ਵਿਰਸੇ ਵਿੱਚ ਪ੍ਰਾਪਤ ਹੋਈ। ਮੈਟ੍ਰਿਕ ਪਾਸ ਕਰਨ ਪਿੱਛੋਂ ਆਪ ਜੀ ਧਾਰਮਿਕ ਵਿੱਦਿਆ ਦੀ ਪ੍ਰਾਪਤੀ ਵਿੱਚ ਜੁੱਟ ਗਏ ਅਤੇ ਸੰਤ ਬਾਬਾ ਰਾਮ ਦਾਸ ਜੀ, ਸੰਤ ਬਾਬਾ ਕੌਕ ਦਾਸ ਜੀ ਅਤੇ ਸੁਪ੍ਰਸਿੱਧ ਹਕੀਮ ਸ੍ਰ: ਅਮਰ ਸਿੰਘ ਜੀ ਖਤਰਾਵਾਂ ਵਾਲਿਆਂ ਦੀ ਅਗਵਾਈ ਹੇਠ ਆਪ ਨੇ ਧਾਰਮਿਕ ਗ੍ਰੰਥਾਂ ਦਾ ਡੂੰਘਾ ਅਧਿਐਨ ਕੀਤਾ ਅਤੇ ਇਸ ਖੇਤਰ ਵਿੱਚ ਆਪਣੇ ਇਲਾਕੇ ਦੀ ਮੰਨੀ-ਪ੍ਰਮੰਨੀ ਸ਼ਖ਼ਸੀਅਤ ਵਜੋਂ ਉੱਭਰੇ।\n\n1965 ਵਿੱਚ ਸੰਗਤਾਂ ਨੇ ਆਪ ਜੀ ਨੂੰ ਪਿੰਡ ਵਿਚਲੇ ਗੁਰਦੁਆਰਾ ਪਾਤਸ਼ਾਹੀ ਪੰਜਵੀਂ ਦਾ ਪ੍ਰਧਾਨ ਸਥਾਪਤ ਕਰ ਦਿੱਤਾ, ਜਿਸ ਅਹੁਦੇ ਤੇ ਆਪ 1979 ਤੱਕ ਸੇਵਾ ਕਰਦੇ ਰਹੇ। ਇੱਥੋਂ ਅਗਲਾ ਕਦਮ ਪੁੱਟਦੇ ਹੋਏ 1979 ਵਿੱਚ ਆਪ ਸ਼੍ਰੋਮਣੀ ਗੁਰਦੁਆਰਾ ਪ੍ਰਬੰਧਕ ਕਮੇਟੀ ਦੇ ਸਭ ਤੋਂ ਵੱਧ ਵੋਟਾਂ ਲੈ ਕੇ ਮੈਂਬਰ ਬਣੇ। ਆਪਣੀ ਮਿਹਨਤ, ਲਗਨ, ਈਮਾਨਦਾਰੀ ਅਤੇ ਨਿਸ਼ਕਾਮ ਸੇਵਾ ਸਦਕਾ ਛੇਤੀ ਹੀ ਆਪ ਸ਼੍ਰੋਮਣੀ ਗੁਰਦੁਆਰਾ ਪ੍ਰਬੰਧਕ ਕਮੇਟੀ ਦੀਆਂ ਮੋਹਰੀਆਂ ਵਿੱਚ ਗਿਣੇ ਜਾਣ ਲੱਗੇ।\n\nਇਸ ਦੌਰਾਨ ਆਪ ਜੀ ਨੂੰ ਸੰਤ ਫਤਹਿ ਸਿੰਘ, ਸੰਤ ਚੰਨਣ ਸਿੰਘ, ਸਰਦਾਰ ਪ੍ਰਤਾਪ ਸਿੰਘ ਕੈਰੋਂ, ਸ੍ਰ: ਕਪੂਰ ਸਿੰਘ ਆਈ. ਸੀ. ਐੱਸ. ਅਤੇ ਸੰਤ ਹਰਚੰਦ ਸਿੰਘ ਲੌਂਗੋਵਾਲ ਨਾਲ ਕੰਮ ਕਰਨ ਦਾ ਮੌਕਾ ਵੀ ਮਿਲਿਆ ਅਤੇ ਦੋ ਵਾਰ ਆਪ ਸ਼੍ਰੋਮਣੀ ਗੁਰਦੁਆਰਾ ਪ੍ਰਬੰਧਕ ਕਮੇਟੀ ਦੇ ਸੀਨੀਅਰ ਮੀਤ ਪ੍ਰਧਾਨ ਬਣੇ। ਅਤਿਅੰਤ ਨਿਸ਼ਕਾਮ ਸੇਵਕ, ਈਮਾਨਦਾਰ ਅਤੇ ਸੱਚੇ-ਸੁੱਚੇ ਹੋਣ ਕਾਰਨ ਹੀ ਆਪ ਜੀ ਜਥੇਦਾਰ ਗੁਰਚਰਨ ਸਿੰਘ ਟੌਹੜਾ, ਸ੍ਰ: ਸੁਰਜੀਤ ਸਿੰਘ ਬਰਨਾਲਾ ਅਤੇ ਸ੍ਰ: ਪ੍ਰਕਾਸ਼ ਸਿੰਘ ਬਾਦਲ ਸਾਰਿਆਂ ਦੇ ਹੀ ਵਿਸ਼ਵਾਸਪਾਤਰ ਹਨ। ਸ਼੍ਰੋਮਣੀ ਗੁਰਦੁਆਰਾ ਪ੍ਰਬੰਧਕ ਕਮੇਟੀ ਦੇ ਮੈਂਬਰ ਤੇ ਅਹੁਦੇਦਾਰ ਵਜੋਂ ਜੋ ਸੇਵਾ ਆਪ ਨੇ ਨਿਭਾਈ ਉਹ ਮਿਸਾਲੀ ਹੈ।\n\nਕਈ ਵੇਰਾਂ ਪਾਕਿਸਤਾਨ ਅਤੇ ਵਿਦੇਸ਼ਾਂ ਨੂੰ ਜਾਣ ਵਾਲੇ ਡੈਲੀਗੇਸ਼ਨਾਂ ਦੀ ਅਗਵਾਈ ਆਪ ਨੇ ਕੀਤੀ ਪਰੰਤੂ ਕਿਰਾਏ ਜਾਂ ਟੀ. ਏ., ਡੀ. ਏ. ਦਾ ਇੱਕ ਵੀ ਪੈਸਾ ਐੱਸ. ਜੀ. ਪੀ. ਸੀ. ਪਾਸੋਂ ਨਹੀਂ ਲਿਆ। ਗੁਰਦੁਆਰਾ ਰਾਮਸਰ ਜੀ ਵਿਖੇ ਸਥਾਪਤ ਐੱਸ. ਜੀ. ਪੀ. ਸੀ. ਦੀ ਗੋਲਡਨ ਆਫਸੈੱਟ ਪ੍ਰੈੱਸ ਆਪ ਜੀ ਦੀ ਮਿਹਨਤ ਅਤੇ ਯਤਨਾਂ ਦੀ ਹੀ ਉਪਜ ਹੈ, ਜੋ ਅੱਜ ਧਾਰਮਿਕ ਸਾਹਿਤ ਛਾਪਣ ਵਾਲੀ ਮੋਹਰੀ ਪ੍ਰੈੱਸ ਹੈ।\n\nਗੁਰੂ ਰਾਮਦਾਸ ਰਿਸਰਚ ਤੇ ਮੈਡੀਕਲ ਇੰਸਟੀਚਿਊਟ ਨੂੰ ਸਥਾਪਤ ਕਰਨ ਵਿੱਚ ਆਪ ਜੀ ਦਾ ਯੋਗਦਾਨ ਬਹੁਤ ਉੱਘਾ ਹੈ। ਆਪਣੀ ਪ੍ਰੇਰਨਾ ਨਾਲ ਆਪ ਜੀ ਇਸ ਸੰਸਥਾ ਲਈ ਲਗਭਗ 55 ਏਕੜ ਦੀ ਵਡਮੁੱਲੀ ਜ਼ਮੀਨ ਲਾਗਲੇ ਪਿੰਡਾਂ ਕੋਲੋਂ ਐੱਸ. ਜੀ. ਪੀ. ਸੀ. ਨੂੰ ਦਿਵਾਉਣ ਵਿੱਚ ਸਫ਼ਲ ਹੋਏ। ਅੱਜ ਤੱਕ ਇਸ ਸੰਸਥਾ ਨਾਲ ਸਬੰਧਤ ਉਸਰ ਰਹੀਆਂ ਇਮਾਰਤਾਂ ਦੀ ਦੇਖ-ਰੇਖ ਵੀ ਆਪ ਜੀ ਨਿਸ਼ਕਾਮ ਤੌਰ ਤੇ ਕਰ ਰਹੇ ਹਨ।\n\nਐੱਸ. ਜੀ. ਪੀ. ਸੀ. ਦੇ ਸਾਰੇ ਐਜੂਕੇਸ਼ਨਲ ਅਦਾਰਿਆਂ ਦੇ ਮੁੱਖ ਟਰੱਸਟੀਆਂ ਵਿੱਚ ਆਪ ਸ਼ਾਮਲ ਹਨ। ਸ਼੍ਰੋਮਣੀ ਕਮੇਟੀ ਤੋਂ ਬਿਨਾਂ ਆਪ ਨੇ ਆਪਣੇ ਨਗਰ ਨਿਵਾਸੀਆਂ ਦੇ ਜੀਵਨ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਜੋ ਸੇਵਾ ਕੀਤੀ ਹੈ ਉਹ ਸਾਡੇ ਸਾਰਿਆਂ ਲਈ ਇੱਕ ਆਦਰਸ਼ ਹੈ। ਗੁਰਦੁਆਰਾ ਸਾਹਿਬ ਕੰਪਲੈਕਸ ਦੀ ਸ਼ਾਨਦਾਰ ਇਮਾਰਤ ਤੋਂ ਬਿਨਾਂ ਇੱਕ ਅਤੀ ਉੱਚ ਦਰਜੇ ਦੀ ਫ੍ਰੀ ਡਿਸਪੈਂਸਰੀ ਅਤੇ ਇੱਕ ਸ਼ਾਨਦਾਰ ਲਾਇਬ੍ਰੇਰੀ ਆਪਣੇ ਨਗਰ ਨਿਵਾਸੀਆਂ ਨੂੰ ਆਪ ਜੀ ਦੀ ਵਡਮੁੱਲੀ ਦੇਣ ਹੈ। ਆਪ ਜੀ ਦੀ ਲਾਇਬ੍ਰੇਰੀ ਵਿੱਚ 150 ਦੇ ਕਰੀਬ ਹੱਥ-ਲਿਖਤ ਖਰੜੇ ਹਨ, ਜਿਨ੍ਹਾਂ ਵਿੱਚੋਂ ਕਈ ਹੋਰ ਕਿਧਰੇ ਵੀ ਉਪਲਬਧ ਨਹੀਂ ਹਨ। ਦੇਸ਼-ਵਿਦੇਸ਼ ਤੋਂ ਨੇਤਾ, ਆਗੂ ਅਤੇ ਬੁੱਧੀਜੀਵੀ ਇਸ ਨੂੰ ਉਚੇਚੇ ਤੌਰ ਤੇ ਵੇਖਣ ਲਈ ਪਧਾਰਦੇ ਹਨ।\n\nਅੱਜ ਮਿਤੀ 12 ਅਕਤੂਬਰ, 2003 ਦਿਨ ਐਤਵਾਰ ਨੂੰ ਸ੍ਰੀ ਗੁਰੂ ਰਾਮ ਦਾਸ ਜੀ ਦੇ 469ਵੇਂ ਅਵਤਾਰ ਪੁਰਬ ਅਤੇ ਅੰਮ੍ਰਿਤਸਰ ਦੀ ਪਾਵਨ ਨਗਰੀ ਦੇ 426ਵੇਂ ਸਥਾਪਨਾ ਦਿਵਸ ਦੇ ਅਵਸਰ ਤੇ ਨਗਰ ਨਿਵਾਸੀਆਂ ਵੱਲੋਂ ਸਥਾਪਤ ਵਿਸ਼ੇਸ਼ ਸੇਵਾ ਅਵਾਰਡ ਨਾਲ ਆਪ ਜੀ ਨੂੰ ਸਨਮਾਨਤ ਕਰਦਿਆਂ ਅਸੀਂ ਵੱਡੀ ਖੁਸ਼ੀ ਅਤੇ ਮਾਣ ਮਹਿਸੂਸ ਕਰਦੇ ਹਾਂ ਅਤੇ ਆਪ ਜੀ ਦੀ ਚੰਗੀ ਸਿਹਤ ਅਤੇ ਲੰਮੀ ਆਯੂ ਲਈ ਅਕਾਲ ਪੁਰਖ ਦੇ ਚਰਨਾਂ ਵਿੱਚ ਅਰਦਾਸ ਕਰਦੇ ਹਾਂ।$bio$,\n  achievements = $bio$According to the sanman-pattar read on 12 October 2003, the residents of Amritsar honoured him with their Special Service Award. The occasion was the 469th birth anniversary of Sri Guru Ram Das Ji and the 426th foundation day of Amritsar.\n\nA separate Award of Honour tray from Sri Guru Ram Das Institute of Medical Sciences & Research, Sri Amritsar, is inscribed “Jathedar Dalip Singh Mallu Nangal” and “Shukrana Divas (February-01-2003)”.\n\nThe same letter says the sangat made him president of Gurdwara Patshahi Panjvi in the village in 1965, that he served in that office until 1979, and that in 1979 he became a member of the Shiromani Gurdwara Parbandhak Committee with the highest number of votes. It also says he was twice senior vice-president of the committee.$bio$,\n  contributions = $bio$The 12 October 2003 letter credits him with these, and this page does not add to that account:\n\n- He studied Sikh scripture under Sant Baba Ram Das Ji, Sant Baba Kauk Das Ji, and Hakim Sardar Amar Singh Ji of Khatrawan.\n- He worked with Sant Fateh Singh, Sant Channan Singh, Sardar Pratap Singh Kairon, Sardar Kapur Singh, and Sant Harchand Singh Longowal.\n- He led delegations to Pakistan and abroad, and took no fare or T.A./D.A. from the SGPC.\n- The SGPC Golden Offset Press at Gurdwara Ramsar is described as the result of his effort.\n- He helped the SGPC obtain about 55 acres from nearby villages for the Guru Ram Das research and medical institute, and the letter says he was still overseeing its buildings without pay.\n- He is named among the chief trustees of the SGPC’s educational institutions.\n- Besides the gurdwara complex, a free dispensary and a library of about 150 handwritten manuscripts are described as his gift to the residents.$bio$,\n  connection = $bio$Born on 2 February 1931 in ਮੱਲੂ ਨੰਗਲ, about 13 kilometres from Amritsar. His early schools were the village primary school, the school at Jagdev Kalan, and Khalsa School at Guru Ke Bagh. From 1965 to 1979 he was president of Gurdwara Patshahi Panjvi in the village.$bio$,\n  sources = 'Sanman-pattar read on 12 October 2003 by the residents of Amritsar, photographed for this archive. Award of Honour, Sri Guru Ram Das Institute of Medical Sciences & Research, Shukrana Divas, 1 February 2003. Photographs supplied for the archive, October 2026. The life above is the text of that citation; it has not been checked against a second published record.'\nwhere slug = 'jathedar-dalip-singh';\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/jathedar-dalip-singh-gathering.jpg',\n  'Gathering photograph supplied with Jathedar Dalip Singh Ji’s papers. The print is marked Harbans Singh Photo Artist, s/o S. Gurdial Singh Photo Artist, PH. 54611. The individuals are not labelled.',\n  3\nfrom personalities where slug = 'jathedar-dalip-singh'\nand not exists (\n  select 1 from personality_photos p\n  where p.personality_id = personalities.id and p.image = '/images/jathedar-dalip-singh-gathering.jpg'\n);\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/jathedar-dalip-singh-award.jpg',\n  'Award of Honour from Sri Guru Ram Das Institute of Medical Sciences & Research, Sri Amritsar. The base reads Jathedar Dalip Singh Mallu Nangal, Shukrana Divas, 1 February 2003.',\n  4\nfrom personalities where slug = 'jathedar-dalip-singh'\nand not exists (\n  select 1 from personality_photos p\n  where p.personality_id = personalities.id and p.image = '/images/jathedar-dalip-singh-award.jpg'\n);\n\ninsert into personality_photos (personality_id, image, caption, sort_order)\nselect id, '/images/jathedar-dalip-singh-citation.jpg',\n  'The sanman-pattar read on 12 October 2003, when the residents of Amritsar honoured him with the Special Service Award.',\n  5\nfrom personalities where slug = 'jathedar-dalip-singh'\nand not exists (\n  select 1 from personality_photos p\n  where p.personality_id = personalities.id and p.image = '/images/jathedar-dalip-singh-citation.jpg'\n);\n";
